  if (CHAR === 'yeqiu' && on && !keys[k]) { if (k === 'egg') yqLaunch(); else if (k === 'terra') yqShield(); else if (k === 'heal') yqSplash(); else if (k === 'learn') yqHeart(); else if (/^g[1-5]$/.test(k)) yqSkill(+k[1]); }   // Nhất Diệp Chi Thu: E/F/T/Y/1–5
