  sfx('ui');
  S.pops.push({ x: b.x, y: b.y - 90, t: 1.6, text: 'Bản Năng Vô Cực!', c: '#ffffff' });
  const x0 = S.cam.x - 40, x1 = S.cam.x + viewW + 40;
  S.bullets = []; S.tshots = []; S.icicles = [];
  const B = S.boss;
