function applyChar() {
  if (S.maxHp && S.maxHp !== stat().hp) { const k = S.hp / S.maxHp; S.maxHp = stat().hp; S.hp = Math.max(1, Math.round(S.maxHp * k)); }
  if (CHAR === 'saiyan' && S.sx) sxFormUI();
  if ((CHAR === 'asta' || CHAR === 'yuno') && S.cl) clFormUI();   // tên chiêu theo dạng biến hình
  if (CHAR === 'kurumi' && S.ku) kuFormUI();   // tên chiêu Kurumi theo dạng: thường, Rasiel, Lucifugus   // tên chiêu Xayda theo dạng: người, khỉ, Super Saiyan Blue
  const u = CHAR_UI[CHAR], s = u.short;
  $('charBtn').textContent = `Nhân vật: ${u.name} (P)`;
  if (u.simple) {
    document.querySelector('#hint .keys').innerHTML = `<kbd>←</kbd> <kbd>→</kbd> chạy · <kbd>↑</kbd>/<kbd>Space</kbd> nhảy · <kbd>J</kbd> ${s[0]} · <kbd>K</kbd> ${s[3]} · <kbd>P</kbd> đổi nhân vật · <kbd>N</kbd> đổi màn · về đích trong ${TIME_LIMIT / 60} phút`;
    document.querySelector('#hint .tap').textContent = `◀ ▶ chạy · ▲ nhảy · ${u.btn.bolt[0]}: ${s[0]} · ${u.btn.skill[0]}: ${s[3]} · về đích trong ${TIME_LIMIT / 60} phút`;
  } else {
  document.querySelector('#hint .keys').innerHTML = `<kbd>←</kbd> <kbd>→</kbd> chạy · <kbd>↑</kbd>/<kbd>Space</kbd> nhảy · <kbd>J</kbd> ${s[0]}${s[1] ? ` (giữ rồi thả: ${s[1]})` : ''} · <kbd>L</kbd> ${s[2]} · <kbd>Shift</kbd> ${s[3]} · <kbd>U</kbd> ${s[4]}${u.more || ''} · <kbd>P</kbd> đổi nhân vật · <kbd>N</kbd> đổi màn · về đích trong ${TIME_LIMIT / 60} phút`;
  document.querySelector('#hint .tap').textContent = `◀ ▶ chạy · ▲ nhảy · ${u.btn.bolt[0]}${s[1] ? ` (giữ: ${s[1]})` : ''} · ${u.btn.web[0]}: ${s[2]} · ${u.btn.skill[0]}: ${s[3]} · ${u.btn.volt[0]}${CH().cost.volt != null ? `: ${s[4]}` : ' khi đầy'}${u.moreTap || ''} · về đích trong ${TIME_LIMIT / 60} phút`;
  }
  document.querySelectorAll('.touch [data-key="web"], .touch [data-key="volt"]').forEach(el => { el.hidden = !!u.simple; });
  document.querySelectorAll('.touch .sx').forEach(el => { el.hidden = CHAR !== 'saiyan'; });
  document.querySelectorAll('.touch .nm').forEach(el => { el.hidden = CHAR !== 'namek'; });
  document.querySelectorAll('.touch .lf').forEach(el => { el.hidden = CHAR !== 'luffy'; });
  document.querySelectorAll('.touch .ku').forEach(el => { el.hidden = CHAR !== 'kurumi'; });
  document.querySelectorAll('.touch .mr').forEach(el => { el.hidden = CHAR !== 'mereo'; });
  document.querySelectorAll('.touch .zn').forEach(el => { el.hidden = CHAR !== 'zenitsu'; });
  document.querySelectorAll('.touch .zs').forEach(el => { el.hidden = CHAR !== 'zenitsu'; el.textContent = `Tốc ×${znSpd()}`; });
  document.querySelectorAll('.touch .yt').forEach(el => { el.hidden = CHAR !== 'yuutan'; });
  document.querySelectorAll('.touch .yb').forEach(el => { el.hidden = CHAR !== 'yuutan2'; });
  document.querySelectorAll('.touch .tq').forEach(el => { el.hidden = CHAR !== 'thiquy'; });
  document.querySelectorAll('.touch .yta').forEach(el => { el.hidden = CHAR !== 'yuta'; });
  document.querySelectorAll('.touch .ytc').forEach(el => { el.hidden = !isYuta(); });
  document.querySelectorAll('.touch .pk').forEach(el => { el.hidden = CHAR !== 'pika'; });
  document.querySelectorAll('.touch .cl').forEach(el => { el.hidden = CHAR !== 'asta' && CHAR !== 'yuno'; });
  document.querySelectorAll('.touch .yq').forEach(el => { el.hidden = CHAR !== 'yeqiu'; });
  document.querySelectorAll('.touch .gxc').forEach(el => { el.hidden = !GXC[CHAR]; });
  document.querySelectorAll('.touch .lk').forEach(el => { el.hidden = CHAR !== 'luck'; });
  document.querySelectorAll('.touch .yn').forEach(el => { el.hidden = CHAR !== 'yuuna'; });
  document.querySelectorAll('.touch .gb').forEach(el => { el.hidden = CHAR !== 'gabimaru'; });
  document.querySelectorAll('.touch .vg').forEach(el => { el.hidden = !(CHAR === 'goku' || CHAR === 'saiyan' || CHAR === 'vegito') || ytaCp(); el.textContent = CHAR === 'vegito' ? 'Tách' : 'Potara'; });
  document.querySelectorAll('.touch .gk').forEach(el => { el.hidden = !flying(); });
  document.querySelector('.touch [data-key="jump"]').setAttribute('aria-label', flying() ? 'Bay lên' : 'Nhảy');
  $('energyChip').title = `${u.energy}: ` + u.kit.map(([k, t]) => `${k} ${t}`).join(' · ');
  for (const [k, [label, aria]] of Object.entries(u.btn)) {
    const el = document.querySelector(`.touch [data-key="${k}"]`);
    el.textContent = label; el.setAttribute('aria-label', aria);
  }
  const fab = document.querySelector('.boltfab');
  fab.innerHTML = `${u.btn.bolt[0]} <kbd>J</kbd>`;
  fab.setAttribute('aria-label', s[1] ? `${u.btn.bolt[1]}, giữ để dùng ${s[1]}` : u.btn.bolt[1]);
  lastSkill = '';
}
