      ctx.fillStyle = white ? '#ffffff' : '#e8e4dc'; ctx.fillRect(-3.8, 6, 7.6, 1.6);
      ctx.fillStyle = LIMB; ctx.fillRect(-2.2, 7.4, 4.4, 6.4);
      ctx.fillStyle = '#8a5a2a'; ctx.fillRect(-3, 13.4, 6.5, 1.8);
