    ctx.beginPath(); ctx.ellipse(-9, 10, 9, 4, -.5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.fillStyle = HAIR; ctx.strokeStyle = '#d8d2c6';
    ctx.beginPath(); ctx.moveTo(-11, 2);
    for (let i = 0; i <= 8; i++) { const a = Math.PI * (1.05 + i / 8 * .95), r = i % 2 ? 11 : 16 + Math.sin(S.t * 9 + i) * 1.5; ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r - 1); }
