    ctx.beginPath(); ctx.moveTo(-8, -3); ctx.lineTo(-5, -8.5); ctx.lineTo(9, -8.5); ctx.lineTo(10, -2); ctx.lineTo(7, -5); ctx.lineTo(5, -1.5); ctx.lineTo(3, -5); ctx.lineTo(0, -1); ctx.lineTo(-2, -5); ctx.closePath(); ctx.fill();
