  S.lu.curse = null;
  S.pops.push({ x: M.x, y: M.f(M.x) - M.hy - 110, t: 2.2, text: 'LỜI NGUYỀN MÁU TRÀN NGẬP!', c: '#ff2a4a', big: true });
  S.flash = 1; sfx('roar');
  luFx({ k: 'ring', x: M.x, y: M.f(M.x) - M.hy, r0: 20, r1: 420, max: .9, c: '#ff2a4a' });
