  const cg = ctx.createRadialGradient(4, -4, 1, 4, -4, 20); cg.addColorStop(0, 'rgb(255 60 80 / .8)'); cg.addColorStop(1, 'rgb(255 0 40 / 0)');
  ctx.fillStyle = cg; ctx.fillRect(-16, -24, 40, 40);
  ctx.restore();
