  for (let i = 1; i < tips.length; i++) {
    const [px, py] = tips[i - 1], [qx, qy] = tips[i], mxp = (px + qx) / 2, myp = (py + qy) / 2;
    ctx.quadraticCurveTo(mxp * .8 + wx * .2, myp * .8 + wy * .2, qx, qy);
  }
