  ctx.quadraticCurveTo(side * 43, -242, side * 41, -222); ctx.bezierCurveTo(side * 39, -196, side * 25, -181, side * 4, -175); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#3a3642'; ctx.lineWidth = 1.2;
