  const ROBE = '#2c3442', ROBE2 = '#1c222e', ROBEL = '#465064', SASH = '#ece8de', SASH2 = '#c8c2b4', SK = '#f4d6bc', SKD = '#d8b096',
    HAIR = '#f6f6f8', HAIRS = '#c8ccd8', HAIRD = '#9aa0b0', GAUNT = '#14161c', GAIT = '#3a4252', STRAW = '#caa868', EYE = '#e8c020';
