  ctx.strokeStyle = SASH2; ctx.lineWidth = 1; for (const [x, y] of [[-22, 10], [-17, 14]]) { ctx.beginPath(); ctx.moveTo(x, hy + y + wave * 2); ctx.lineTo(x - 2, hy + y + 4 + wave * 2); ctx.moveTo(x, hy + y + wave * 2); ctx.lineTo(x + 2, hy + y + 4 + wave * 2); ctx.stroke(); }
