      if (Math.abs(u.x - shade) < 30) { C.baby = false; C.dawn = 60; C.burn = 0; icSay('Hà… bóng râm…', 2); S.pops.push({ x: u.x, y: u.y - 200, t: 2, text: 'Muzan trốn vào bóng râm! Bình minh lùi lại', c: '#ff4a5a', big: true }); }
