    if (C.ph === 1) { C.cine = { k: 'regrow', t: 0 }; B.hp = 1; icSay('…', 1); S.pops.push({ x: u.x, y: u.y - 200, t: 2, text: 'CHẶT ĐẦU KOKUSHIBO!', c: '#ffe27a', big: true }); sfx('hit'); return; }
