  ctx.fillStyle = '#5a2a6a'; ctx.beginPath(); ctx.moveTo(-20, -132); ctx.lineTo(20, -132); ctx.lineTo(18, -68); ctx.lineTo(-18, -68); ctx.closePath(); ctx.fill();
