  ctx.fillStyle = '#1e1a26'; ctx.beginPath(); ctx.moveTo(-22, -134); ctx.lineTo(-30, -60); ctx.lineTo(-20, -62); ctx.lineTo(-10, -128); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#e8e0d0'; ctx.fillRect(-18, -74, 36, 5);   // đai
