  ctx.fillStyle = '#e8c020'; for (let i = 20; i < L; i += 18) { ctx.beginPath(); ctx.ellipse(i, 0, 3, 2, 0, 0, Math.PI * 2); ctx.fill(); ctx.fillStyle = '#100006'; ctx.fillRect(i - .5, -1.5, 1, 3); ctx.fillStyle = '#e8c020'; }
