  const F = ARENA.floor, T = A.t - A.W, C = B.sk, st = skStage(B), atk = st.atk * (C.kishi ? 1.3 : 1), col = SK_EL[skEl(B)][1];
  const end = r => { B.act = null; B.atkT = r * (C.kishi ? .8 : 1); };
