      for (let i = 0; i < n; i++) { const a = a0 + (i - (n - 1) / 2) * (A.type === 'invis' ? .22 : .16); skShot({ x: sx, y: sy, vx: Math.cos(a) * (A.type === 'blades' ? 820 : 560), vy: Math.sin(a) * (A.type === 'blades' ? 820 : 560), k: A.type, home: A.type === 'orbs', atk: atk * .8, col }); }
