  if (guards < (D.ph === 1 ? 2 : 3)) kit.push('guards');
  if (D.ph >= 2) { kit.push('car'); if (!S.enemies.some(e => e.alive && e.decoy)) kit.push('face'); }
  if (D.ph >= 3) kit.push('snipe', 'cash', 'cash');
