    if (T >= 0 && !A.done) { A.done = true; sfx('boom'); if (Math.hypot(b.x - s.x, b.y - s.y) < R + 16) mhStrike(atk * 1.4); mhFx({ k: 'flash', x: s.x, y: s.y, max: .15 }); D.snipe = null; }
    if (T > .3) end(.6);
