function newYq() { return { cd: {}, pose: null, poseT: 0, cur: null, mt: 0, ci: 0, ciT: 0, hits: 0, hitT: 0, tier: 0, runes: [], bolts: [], buffs: {}, shield: false, fx: [], ghosts: [], gT: 0, pend: [], ult: null, spin: 0, dive: null, splashT: 0, bleeds: [], stagT: 0 }; }
