  if (!T.auto && !T.form && T.tf <= 0 && S.maxHp && S.hp < S.maxHp / 2) { T.auto = true; T.cd.f = 0; tqTransform(); }   // máu dưới 50%: tự Quỷ Thi Giải
  // hợp thể
