  ctx.fillStyle = ec; ctx.beginPath(); ctx.ellipse(0, -161, .7, 1.8, 0, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = '#b8323e'; ctx.lineWidth = 1.4; ctx.beginPath(); ctx.moveTo(-2.5, -142); ctx.quadraticCurveTo(0, -140.8, 2.5, -142); ctx.stroke();
