      for (const [w, a, c] of [[16, .3, '#5a8aff'], [7, .7, YTA_CE], [2.5, 1, '#ffffff']]) { ctx.strokeStyle = c; ctx.globalAlpha = a * (1 - k); ctx.lineWidth = w; ctx.beginPath(); ctx.arc(0, 0, f.r, Math.min(f.a0, f.a1), Math.max(f.a0, f.a1)); ctx.stroke(); }
