  drawKuFigure(b.x, fy, d, { run: false, air, float: true, lean, ph: b.run, musket: S.charging && S.chargeT > BALL_HOLD && !K.rasiel && !K.inv && !K.wq && !K.crim, aim: S.charging, rasiel: K.rasiel, inv: K.inv, wq: K.wq, crim: K.crim });
