  const bob = running ? Math.abs(Math.sin(ph)) * 2.5 : 0;
  const HAIR = '#e8742a', HAIRD = '#a8481a', SKIN = '#f6dcc4', ROBE = '#15141a', CLOUD = '#d2232a', DK = '#0e0e12', RIN = '#b9a6e8';
  // Shinra Tensei đang toả: Pain lơ lửng giữa luồng chakra
