  for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.arc(hx - 6.5, hy - 3 + i * 2.4, .8, 0, Math.PI * 2); ctx.fill(); }
  ctx.strokeStyle = '#6a4a3a'; ctx.lineWidth = 1;
