  aura.addColorStop(0, 'rgb(255 60 100 / .38)'); aura.addColorStop(.6, 'rgb(255 40 90 / .16)'); aura.addColorStop(1, 'rgb(255 40 90 / 0)');
  ctx.fillStyle = aura;
