      const g = ctx.createRadialGradient(cx - r * .3, cy - r * .4, r * .2, cx, cy, r * 1.3);
      g.addColorStop(0, '#ffc2cc'); g.addColorStop(.5, '#ff3d64'); g.addColorStop(1, '#a80c34');
      ctx.fillStyle = g;
