  ctx.save(); ctx.translate(-8, -9); ctx.rotate(-.12 + Math.sin(T * 3) * .07 + (running ? Math.sin(ph) * .06 : 0));
  const tail = [[1.5, -.5], [-3, -3.5], [-1, -6.5], [-8, -10], [-5, -14], [-15, -19], [-10, -25], [-23, -31], [-12, -33], [-16, -27], [-6, -21], [-9, -17], [-1, -12], [-3, -9], [2.5, -4]];
