  ctx.bezierCurveTo(-10, -23, -12.5, -10, -10.5, -4.5);
  ctx.bezierCurveTo(-9, -1, 8, -1, 9.5, -4.5);
  ctx.bezierCurveTo(12, -10, 9, -23, -1, -23);
  ctx.fillStyle = yel(-1, -12, 12); ctx.fill();
